5	/**
6	 * Works out an invoice's status from the payments recorded against it, instead of a hand-set flag: a
7	 * DRAFT (not yet sent) keeps its stored lifecycle status, but once an invoice is SENT its status is
8	 * derived — SENT while nothing is paid, PARTIAL once some of the amount is covered, and PAID once the
9	 * payments cover it in full. Kept in one place so the per-project list, the invoice detail page and
10	 * the all-invoices view all agree on the same rule.
11	 */
12	public final class InvoiceStatus {
13	
14	    private InvoiceStatus() {
15	    }
16	
17	    /**
18	     * @param baseStatus the invoice's stored lifecycle status (e.g. DRAFT, SENT).
19	     * @param amount     what the invoice totals (its line items), null-safe.
20	     * @param paid       the sum of its payments, null-safe.
21	     * @return the status to show: the stored status for anything not yet SENT; otherwise SENT /
22	     *         PARTIAL / PAID worked out from the payments.
23	     */
24	    public static String derive(String baseStatus, BigDecimal amount, BigDecimal paid) {
25	        if (!"SENT".equals(baseStatus)) {
26	            // Not yet sent — payments do not apply; keep the lifecycle status as stored.
27	            return baseStatus;
28	        }
29	        BigDecimal paidAmount = paid != null ? paid : BigDecimal.ZERO;
30	        if (paidAmount.signum() <= 0) {
31	            return "SENT";
32	        }
33	        if (amount != null && paidAmount.compareTo(amount) >= 0) {
34	            return "PAID";
35	        }
36	        return "PARTIAL";
37	    }
38	}
