12	 * {@code projects} table (Flyway V3). The id is database-generated (IDENTITY) on create; the seed
13	 * path inserts explicit ids directly via JdbcTemplate (see {@link TestSupportController}).
14	 */
15	@Entity
16	@Table(name = "projects")
17	public class Project {
18	
