20	    @GeneratedValue(strategy = GenerationType.IDENTITY)
21	    private Long id;
22	
23	    private String name;
24	
25	    @Column(name = "client_id")
26	    private Long clientId;
27	
28	    // Archived projects are tucked away: kept in the table but dropped off the lists (Flyway V15).
29	    private boolean archived;
30	
31	    public Project() {
32	    }
33	
